{
  "assessment": "Haiti's economy is struggling with negative growth (-3.3%) and high inflation (24.5%), while public mood remains discontented. With a low military budget and unstable security loyalty, we must prioritize stabilizing domestic order while boosting economic recovery. We will accept Liechtenstein's diplomatic overture and focus resources on infrastructure and health to relieve economic pressure.",
  "directives": [
    {
      "type": "set_tax",
      "target": null,
      "amount": 11.0,
      "sub": "",
      "order": "Set tax revenue to 11% of GDP to slightly increase fiscal room."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 3.5,
      "sub": "infrastructure",
      "order": "Increase infrastructure spending to 3.5% of GDP to stimulate employment and economic recovery."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.5,
      "sub": "health",
      "order": "Increase health spending to 2.5% of GDP to address public needs and ease discontent."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": -0.5,
      "sub": "",
      "order": "Lower the policy rate by 0.5 percentage points to encourage lending and growth."
    },
    {
      "type": "trade_deal_accept",
      "target": "LIE",
      "amount": 0,
      "sub": "",
      "order": "Accept the trade and cooperation proposal from Liechtenstein."
    }
  ],
  "cables": [
    {
      "to": "LIE",
      "private": true,
      "text": "We accept your proposal for deeper cooperation on trade and security, and look forward to strengthening our bilateral ties."
    }
  ],
  "public_statement": "The government is taking decisive steps to revitalize the economy, expand essential infrastructure, and improve public health services to ensure a more prosperous future for all Haitians.",
  "standing_orders": [
    {
      "when": "inflation_above:20",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 0.5,
        "sub": "",
        "order": "Raise interest rates to combat high inflation if it remains above 20%."
      }
    }
  ],
  "detailed_report": "economy"
}
